&lt;ActionGrid&gt;
  &lt;Settings&gt;
    &lt;Version&gt;5.28.0&lt;/Version&gt;
    &lt;Build&gt;5.28.314&lt;/Build&gt;
    &lt;CurrentContext&gt;ExportImport&lt;/CurrentContext&gt;
    &lt;ModuleId&gt;1539&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;SELECT
    s.Id AS Id,
    s.CodSucursala,
    s.DenumireSucursala,

    @Anul AS Anul,
    @Luna AS Luna,

    COUNT(tm.Id) AS NumarPozitii,

    ISNULL(
        SUM(ISNULL(tm.NrTMTotal, 0)),
        0
    ) AS TotalTichete,

    ISNULL(
        SUM(ISNULL(tm.SumaTicheteMasa, 0)),
        0
    ) AS ValoareTotala,

    CASE
        WHEN ef.FileId IS NULL THEN N&#39;Nu&#39;
        ELSE N&#39;Da&#39;
    END AS FisierGenerat,

    CASE
        WHEN total.TotalSucursale &amp;gt; 0
         AND generate.FisiereGenerate = total.TotalSucursale
        THEN 1
        ELSE 0
    END AS ToateFisiereleGenerate,

    ef.FileId,
    ef.DenumireFisier,
    ef.DataGenerare

FROM app.Sucursala AS s

LEFT JOIN app.TichetMasa AS tm
    ON LTRIM(RTRIM(tm.CodSucursala))
        = LTRIM(RTRIM(s.CodSucursala))
   AND tm.Anul = @Anul
   AND tm.Luna = @Luna

OUTER APPLY
(
    SELECT TOP (1)
        fe.FileId,
        fe.DenumireFisier,
        fe.DataGenerare
    FROM app.FisierEdenred AS fe
    INNER JOIN Files AS f
        ON f.FileId = fe.FileId
    WHERE LTRIM(RTRIM(fe.CodSucursala))
        = LTRIM(RTRIM(s.CodSucursala))
      AND fe.Anul = @Anul
      AND fe.Luna = @Luna
    ORDER BY
        fe.DataGenerare DESC,
        fe.Id DESC
) AS ef

CROSS JOIN
(
    SELECT
        COUNT(*) AS TotalSucursale
    FROM app.Sucursala
) AS total

CROSS JOIN
(
    SELECT
        COUNT(
            DISTINCT LTRIM(RTRIM(fe2.CodSucursala))
        ) AS FisiereGenerate
    FROM app.FisierEdenred AS fe2
    INNER JOIN Files AS f2
        ON f2.FileId = fe2.FileId
    INNER JOIN app.Sucursala AS s2
        ON LTRIM(RTRIM(s2.CodSucursala))
         = LTRIM(RTRIM(fe2.CodSucursala))
    WHERE fe2.Anul = @Anul
      AND fe2.Luna = @Luna
) AS generate

GROUP BY
    s.Id,
    s.CodSucursala,
    s.DenumireSucursala,
    ef.FileId,
    ef.DenumireFisier,
    ef.DataGenerare,
    total.TotalSucursale,
    generate.FisiereGenerate

ORDER BY
    s.CodSucursala;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;IdColumn&quot;:&quot;Id&quot;,&quot;SqlQueryColumns&quot;:&quot;&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:&quot;Id&quot;,&quot;Name&quot;:&quot;Id&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;CodSucursala&quot;,&quot;Name&quot;:&quot;CodSucursala&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;DenumireSucursala&quot;,&quot;Name&quot;:&quot;DenumireSucursala&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Anul&quot;,&quot;Name&quot;:&quot;Anul&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Luna&quot;,&quot;Name&quot;:&quot;Luna&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;NumarPozitii&quot;,&quot;Name&quot;:&quot;NumarPozitii&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TotalTichete&quot;,&quot;Name&quot;:&quot;TotalTichete&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;ValoareTotala&quot;,&quot;Name&quot;:&quot;ValoareTotala&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;FisierGenerat&quot;,&quot;Name&quot;:&quot;FisierGenerat&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;ToateFisiereleGenerate&quot;,&quot;Name&quot;:&quot;ToateFisiereleGenerate&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;FileId&quot;,&quot;Name&quot;:&quot;FileId&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;DenumireFisier&quot;,&quot;Name&quot;:&quot;DenumireFisier&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;DataGenerare&quot;,&quot;Name&quot;:&quot;DataGenerare&quot;,&quot;TypeStr&quot;:&quot;System.DateTime, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null}]}&lt;/DataSource&gt;
    &lt;ShowTitle&gt;True&lt;/ShowTitle&gt;
    &lt;NoDataMessage&gt;No Data&lt;/NoDataMessage&gt;
    &lt;AditionalHtmlHeader /&gt;
    &lt;OnInitJs /&gt;
    &lt;OnRefreshJs /&gt;
    &lt;EnableEmbed&gt;False&lt;/EnableEmbed&gt;
    &lt;ShowCondition /&gt;
    &lt;SearchPlaceholder&gt;Search&lt;/SearchPlaceholder&gt;
